export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女はメモを裏返した。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ペン先が長いこと止まった。看護記録なら何千枚と書いてきたけれど、こんなに考えこんだことは一度もない。意識清明、バイタル安定、主訴なし。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "結局、こう書いた。「靴下はこちらで預かっています。状態は安定。勇気については、洗濯機は『見ていない』とのこと。経過観察を推奨します。」", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）……申し送りみたいになった。まあ、いいか。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "メモをチャック袋に戻し、灰色の靴下に押しこんで、彼の洗濯物の袋の上に置く。それから四つ目の椅子に戻って、服をたたみはじめた。ものすごく、ゆっくりと。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "五分後、ドアが開いた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は雨のにおいをまとって入ってきた。手にはホットの豆乳のボトル。適当につかんできたように見えた。なぜそれを持っているのか、本人もよく分かっていないようだったから。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "靴下に気づいて、彼は動きを止めた。座って、チャック袋を開けて、読む。長いこと読んでいた。外国語で書いてしまったのかと、彼女が不安になるくらいに。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "それから赤ペンのキャップを抜いて何か書きつけ、たたみ直すと、靴下を二人のあいだの空いた椅子に置いた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "何も言わずに。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）……なるほど。そういうルールね。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "手に取る。「入院を受け入れてくださり、ありがとうございます。家族より質問です。勇気が三号のゴムパッキンに挟まっている可能性はありますか。」", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）私の書式をまねしてる。翻訳者だもの、まねするに決まってる。", background: Background.Branch_1a_B1a_Act4_S0, portrait: Portrait.ZhouYining_Smile },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は書いた。「ゴムパッキン確認済み。十元硬貨一枚と、持ち主不明の髪の毛一本を発見。勇気は発見に至らず。」そして真ん中の椅子に戻す。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "読み終えた彼の肩が、一度だけ震えた。笑いをこらえているのだと、彼女には確信があった。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「十元あれば、二号がもう一回まわります。初診料としてお納めください。」", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「当院では初診料はいただいておりません。ただ、ご家族が毎週四号を譲り、乾いていない服を持ち帰っておられる件については、当院でもずっと気にかけておりました。」", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "今度は、彼の手が長いこと止まった。戻ってきたメモの字は小さくなっていた。場所を取るのを遠慮しているみたいに。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "「眠れないとき、ここに来ていました。そのうち、木曜日は少しよく眠れることに気づきました。」", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "その一行を、彼女は三回読んだ。外の雨は、いつのまにかやんでいた。", background: Background.Branch_1a_B1a_Act4_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "ガラスにはまだ水滴が残っている。空は黒から薄れて、何度も洗ったような灰青色になっていた。向かいのコンビニの灯りが、朝の光の中で急にひどく疲れて見えた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "メモの裏はもう埋まっていた。表に返し、「勇気」の二文字の横の余白に、最後の一行を書く。「周以寧。準夜勤。木曜日。」", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "椅子には置かなかった。立ち上がって空いた椅子の前を通りすぎ、メモを彼の手に直接渡した。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼が顔を上げる。近くで見ると、クマは思っていたよりずっと深かった。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "……江遠。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "江遠といいます。すみません、先に書くべきでした。僕は、口より字のほうが器用なので。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Smile },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "知ってます。壁の貼り紙を直したのも、江遠さんですよね。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "動物を入れるな、とは書いてあったので。人のことも書いておくべきかと。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "用意周到ですね。チャック袋と同じくらい。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼の耳がまた赤くなった。今回は呼吸を数えないでおこう、と彼女は決めた。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼が豆乳を差し出した。とっくに熱くはなく、ぬるくなっていた。四号で半分だけ乾かした服みたいに。", background: Background.Branch_1a_B1a_Act4_S1 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "これ、本当は周さんに買ったんです。向かいで立っている時間が、長すぎただけで。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "ぬるいくらいがちょうどいいです。仕事明けは、熱いのは飲めないので。", background: Background.Branch_1a_B1a_Act4_S1, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "二人は一緒に店を出た。アーケードの下にはスクーターが二台。彼女のと、彼のと、そのあいだに知らない誰かのが一台。", background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "この半年、二人のあいだにはずっと、知らない誰かのスクーターが一台はさまっていたのだ。", background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "あの……もう片方の靴下、来週の木曜に持ってきます。ちゃんと一足にします。", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "洗濯機に食べられたって、言ってませんでした？", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Base },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "はい。なんとかして吐き出させます。", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は声を出して笑った。半年で初めて、彼の前で声を出して笑った。", background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "うん。じゃあ、また木曜日に。", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Smile },
    { characterId: CharacterId.RedPen, character: "赤ペン", dialogue: "また木曜日に。", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.RedPen_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "アーケードからスクーターを出したとき、空はまた少し明るくなっていた。ミラーの中で、彼はまだコインランドリーの入口に立っていた。字でびっしり埋まったメモを、とても大事な原稿のように握りしめて。", background: Background.Branch_1a_B1a_Act4_S2 },
    { characterId: CharacterId.ZhouYining, character: "以寧", dialogue: "（心の声）来週の木曜日は、四号を先に譲ってあげよう。", background: Background.Branch_1a_B1a_Act4_S2, portrait: Portrait.ZhouYining_Base },
];
